import java.io.*;class RiverDefaultsTest{public static void main(String[]a)throws Exception{var g=new TerrainGraph();var noise=g.add(TerrainGraph.Type.NOISE,0,0);var river=g.add(TerrainGraph.Type.RIVERS,200,0);var bank=g.add(TerrainGraph.Type.RIVER_BANKS,400,0);var out=g.add(TerrainGraph.Type.OUTPUT,600,0);g.connect(noise.id,river.id,0);g.connect(river.id,bank.id,0);g.connect(bank.id,out.id,0);if(river.p("courses")!=1||river.p("avoidDips")!=1||bank.p("courses")!=1)throw new AssertionError("New nodes do not use replacement system");river.values.remove("courses");river.values.remove("avoidDips");bank.values.remove("courses");var bytes=new ByteArrayOutputStream();g.write(new DataOutputStream(bytes));var old=TerrainGraph.read(new DataInputStream(new ByteArrayInputStream(bytes.toByteArray())));if(old.nodes.get(river.id).p("courses")!=0||old.nodes.get(river.id).p("avoidDips")!=0||old.nodes.get(bank.id).p("courses")!=0)throw new AssertionError("Legacy graph changed silently");System.out.println("PASS: new river nodes use drainage-first routing; older graphs retain saved behavior");}}
